// Generates the `allow-start_sign_in` permission from the command list, so the capability file
// names a permission the build actually emitted rather than one hand-written and hoped for
// (tauri-build 2.7 acl.rs: "permissions autogenerated in the format of `allow-$command`").
fn main() {
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(&["start_sign_in"])),
    )
    .expect("failed to run tauri-build");
}
